test(t => {
  const canvas = new OffscreenCanvas(100, 50);
  const ctx = canvas.getContext('2d', {colorSpace: "srgb"});

  const color_style_1 = 'color(srgb 0 1 1)';
  const color_style_2 = 'color(srgb 0.8 0.2 0.8)';
  const color_spaces = ['srgb', 'srgb-linear', 'display-p3', 'display-p3-linear'];
  const expected_pixels_1 = {'srgb': [0, 255, 255, 255], 'srgb-linear': [0, 255, 255, 255], 'display-p3': [117, 251, 253, 255], 'display-p3-linear': [45, 247, 251, 255]};
  const expected_pixels_2 = {'srgb': [204, 51, 204, 255], 'srgb-linear': [154, 8, 154, 255], 'display-p3': [188, 64, 198, 255], 'display-p3-linear': [128, 13, 143, 255]};
  const epsilon = 2;

  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, 1, 1);
  ctx.fillStyle = color_style_1;
  ctx.fillRect(1, 0, 1, 1);
  ctx.fillStyle = color_style_2;
  ctx.fillRect(0, 1, 1, 1);
  ctx.fillStyle = 'white';
  ctx.fillRect(1, 1, 1, 1);

  for (const img_cs of color_spaces) {
    const image_data = ctx.getImageData(0, 0, 2, 2, {colorSpace: img_cs});
    _assertSame(image_data.colorSpace, img_cs, "image_data.colorSpace", "img_cs");
    const pixels = image_data.data;
    const expected = [
      [0, 0, 0, 255],
      expected_pixels_1[img_cs],
      expected_pixels_2[img_cs],
      [255, 255, 255, 255]
    ];
    for (let i = 0; i < 4; ++i) {
      for (let c = 0; c < 4; ++c) {
        assert_approx_equals(pixels[4 * i + c], expected[i][c], epsilon,
            `Pixel ${i} component ${c} mismatch for img: ${img_cs}`);
      }
    }
  }
}, "Test getImageData color conversions from a srgb canvas");

